// Binary Search

a1 = arr[5, 1, 4, 2, 8]

fun Binary_Search(@init<table> array, target):
    n = length(array)
    low = 0
    high = n - 1

    while (low <= high):
        mid = floor((low + high) / 2)

        @mark<mid, highlight, yellow> val = array[mid]

        if (val == target):
            @mark<mid, highlight, green> return mid
        end if

        if (val < target):
            @mark<low, outline, yellow> low = mid + 1
        end if

        if (val > target):
            @mark<high, outline, yellow> high = mid - 1
        end if
    end while

    @log<warn, "Not found"> return -1
end fun

result = Binary_Search(a1, 4)

