fun Comparison_Counting_Sort(@init<table> array):
    n = length(array)

    count = arr(n)  // create array to store counts

    // initialize the count array
    for (i = 0; i < n; i += 1):
        count[i] = 0
    end for

    // count comparisons
    for (i = 0; i < n - 1; i += 1):
        for (j = i + 1; j < n; j += 1):
            if (array[i] < array[j]):
                count[j] += 1
            else:
                count[i] += 1
            end if
        end for
    end for

    // place elements in sorted order back into array
    for (i = 0; i < n; i += 1):
        array[count[i]] = array[i]
    end for

    return array
end fun

