// Even_Odd_Pivot

a1 = arr[5, 1, 4, 2, 8]

fun Even_Odd_Pivot(@init<table> array, low, high):
    // choose the pivot - first element of sub-array
    @mark<low, highlight, yellow> pivot = array[low]

    // initialize pointers i and j outside bounds of loop
    i = low - 1
    j = high + 1

    while (true):
        // move left pointer forward until even number is found
        while (true):
            i += 1
            @mark<i, outline, yellow> if (array[i] % 2 == 0 or i >= high):
                break
            end if
        end while

        // move right pointer backward until odd number is found
        while (true):
            j -= 1
            @mark<j, outline, yellow> if (array[j] % 2 != 0 or j <= low):
                break
            end if
        end while

        // if pointers cross/meet, then the rearrangement is completed.
        if (i >= j):
            @log<info, "Rearrangement complete"> return array
        end if

        // swap elements at i and j if in the wrong partition
        @mark<i, highlight, green> swap (array[i], array[j])

    end while
end fun

result = Even_Odd_Pivot(a1, 0, length(a1) - 1)

