fun Build_Max_Heap(@init<table> array, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    @mark<left, outline, yellow> if (left < n and array[left] > array[largest]):
        @mark<left, text, fg> largest = left
    end if

    @mark<right, outline, yellow> if (right < n and array[right] > array[largest]):
        @mark<right, text, fg> largest = right
    end if

    @mark<largest, outline, yellow> if (largest != i):
        @swap<i, largest> swap(array[i], array[largest])
        @mark<i, outline, yellow> Build_Max_Heap(array, n, largest)
    end if
end fun

