fun Boyer_Moore_Voting_Algorithm(@init<table> array):
    candidate = -1
    count = 0

    // Phase 1: Finding a potential candidate
    for (i = 0; i < length(array); i += 1):
        @mark<i, outline, yellow> if (count == 0):
            @mark<i, highlight, green> candidate = array[i]
            @mark<i, highlight, green> count = 1
        end if

        @mark<i, outline, yellow> else_if (array[i] == candidate) 
            @mark<i, highlight, green> count += 1
        end_if          (array[i] == candidate)

        @mark<i, outline, yellow> else_if (array[i] != candidate) 
            @mark<i, highlight, green> count -= 1
        end_if          (array[i] != candidate)
    end for

    // Phase 2: Verifying the candidate
    count = 0
    for (i = 0; i < length(array); i += 1):
        @mark<i, outline, yellow> if (array[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if
    end for

    @mark<count, outline, yellow> if (count > floor(length(array) / 2)):
        @mark<cand, highlight, green> return candidate
    end if

    @log<warn, "No majority element"> return -1
end fun

