fun Merge_Sort(@init<table> array):
    n = length(array)
    if (n <= 1):
        return array
    else:
        mid = floor(n / 2)
        left = subarray(array, 0, mid)
        right = subarray(array, mid, n - mid)
        left = Merge_Sort(left)
        right = Merge_Sort(right)
        return Merge(left, right)
    end if
