fun Move_ZerosToEnd(@init<table> array):
    n = length(array)
    zeroPos = 0

    // Find the first zero position
    for (i = 0; i < n; i += 1):
        @mark<i, outline, yellow> if (array[i] == 0):
            @mark<zeroPos, highlight, green> zeroPos = i
            break
        end if
    end for

    // Iterate through the array and move non-zero values
    for (i = zeroPos + 1; i < n; i += 1):
        @mark<i, outline, yellow> if (array[i] != 0):
            @mark<zeroPos, highlight, green> swap(array[i], array[zeroPos])
            zeroPos += 1
        end if
    end for

    return array
end fun

