// Helper function to merge two subarrays
fun Merge(@init<table> left, @init<table> right):
    n1 = length(left)
    n2 = length(right)
    merged = arr(n1 + n2)  // Temporary array to hold merged values
    i = 0
    j = 0
    k = 0

    // Merge the smallest elements from both sides until one is exhausted
    while (i < n1 and j < n2):
        if (left[i] <= right[j]):
            merged[k] = left[i]
            i += 1
        else:
            merged[k] = right[j]
            j += 1
        k += 1
    end if

    // Copy any remaining elements of left, if any
    while (i < n1):
        merged[k] = left[i]
        i += 1
        k += 1
    end while

    // Copy any remaining elements of right, if any
    while (j < n2):
        merged[k] = right[j]
        j += 1
        k += 1
    end while

    return merged
end(fun)

// Main Merge Sort function
fun Merge_Sort(@init<table> array):
    n = length(array)
    if (n <= 1):
        return array
    end if

    mid = floor(n / 2)
    left = Merge_Sort(subarray(array, 0, mid))
    right = Merge_Sort(subarray(array, mid, n))

    return Merge(left, right)
end(fun)

