        elseif (sum < target):
            @mark<i, outline, yellow> i += 1
        else:
            @mark<j, outline, yellow> j -= 1

        @mark<i, outline, yellow> end(i, j)
    end if

    @log<info, "No pair found"> return arr[-1] + -1
end(fun)

