@init<table> a3 = arr[-1, -1]

fun Two_Pointers(@init<table> array, target):
    n = length(array)

    // Initialize two pointers
    i = 0
    j = n - 1

    while (i < j):
        @mark<i, outline, yellow> @mark<j, outline, yellow> sum = array[i] + array[j]

        if (sum == target):
            @log<info, "Pair found"> return arr[i + 1] // Return indices (1-based)
        else if (sum < target):
            @mark<i, highlight, green> i += 1
        else:
            @mark<j, highlight, green> j -= 1
        end if
    end while

    @log<warn, "No pair found"> return arr[-1] // Return [-1, -1] if no pair found
end fun

